#include <iostream>
#include <cstdlib>
#include <ctime>
using std::cout;
using std::endl;

int main()
{
    srand((unsigned int)time(NULL));

    int iBaseball[9] = {};
    for (int i = 0; i < 9; i++)
    {
        iBaseball[i] = i + 1;
    }

    for (int i = 8; i > 0; i--)
    {
        int j = rand() % (i + 1);

        int iTemp = iBaseball[i];
        iBaseball[i] = iBaseball[j];
        iBaseball[j] = iTemp;
    }

    for (int i = 0; i < 9; i++)
    {
        cout << iBaseball[i] << " ";
    }
    cout << endl;

    return 0;
}

