#include <iostream>
using std::cout;
using std::cin;
using std::endl;

int main()
{
    int iBaseball[3] = { 4, 7, 2 };
    int iInput[3];

    for (int i = 0; i < 3; i++)
    {
        cout << "Number " << i + 1 << ": ";
        cin >> iInput[i];
    }

    for (int i = 0; i < 3; i++)
    {
        for (int j = i + 1; j < 3; j++)
        {
            if (iInput[i] == iInput[j])
            {
                cout << "Duplicate" << endl;
                return 0;
            }
        }
    }

    int iStrike = 0, iBall = 0;
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            if (iBaseball[i] == iInput[j])
            {
                if (i == j)
                    iStrike++;
                else
                    iBall++;

                break;
            }
        }
    }

    if (iStrike == 3)
        cout << "You Win!" << endl;
    else if (iStrike == 0 && iBall == 0)
        cout << "Out" << endl;
    else
        cout << iStrike << " Strike " << iBall << " Ball" << endl;

    return 0;
}
